  `onu_mac` varchar(17) DEFAULT NULL,
  `router_mac` varchar(17) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_company_pppoe` (`company_id`,`pppoe_username`),
  UNIQUE KEY `unique_company_customer_id` (`company_id`,`customer_id`),
  KEY `idx_mikrotik` (`mikrotik_id`),
  KEY `idx_mikrotik_id` (`mikrotik_id`),
  KEY `idx_status` (`status`),
  KEY `idx_company_id` (`company_id`)
