DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_payments_after_insert_bill_report
AFTER INSERT ON payments
FOR EACH ROW
BEGIN

    INSERT INTO bill_reports
    (
        company_id,
        payment_id,
        user_id,
        connection_type,
        customer_name,
        area_name,
        pppoe_username,
        package_name,
        bill_amount,
        discount,
        due_amount,
        collected_amount,
        medium,
        bill_type,
        collected_by,
        collector_role,
        note,
        created_at
    )

    SELECT

        /* COMPANY */
        COALESCE(
            NULLIF(NEW.company_id, 0),
            NULLIF(c.company_id, 0),
            NULLIF(u.company_id, 0),
            0
        ) AS company_id,

        /* ORIGINAL PAYMENT ID */
        NEW.id AS payment_id,

        /* CUSTOMER ID */
        COALESCE(c.customer_id, '') AS user_id,

        /* CONNECTION */
        COALESCE(c.connection_type, 'PPPOE') AS connection_type,

        /* CUSTOMER */
        COALESCE(c.name, '') AS customer_name,

        /* SUB AREA FIRST, AREA SECOND */
        COALESCE(
            NULLIF(sa.name, ''),
            NULLIF(a.name, ''),
            ''
        ) AS area_name,

        /* PPPOE */
        COALESCE(c.pppoe_username, '') AS pppoe_username,

        /* PACKAGE */
        COALESCE(c.package_name, '') AS package_name,

        /* MONTHLY BILL */
        COALESCE(c.monthly_bill, 0.00) AS bill_amount,

        /* NO DISCOUNT FIELD IN PAYMENTS */
        0.00 AS discount,

        /*
         * Do not use customers.balance here.
         * The payment INSERT can happen before the customer
         * balance UPDATE inside the recharge transaction.
         *
         * Therefore this is kept at zero.
         */
        0.00 AS due_amount,

        /* ACTUAL COLLECTION */
        COALESCE(NEW.amount, 0.00) AS collected_amount,

        /* PAYMENT METHOD */
        COALESCE(NEW.payment_method, 'Hand Cash') AS medium,

        /* BILL / ADVANCE */
        CASE
            WHEN NEW.is_advance = 1 THEN 'Advance'
            ELSE 'Bill'
        END AS bill_type,

        /* COLLECTOR */
        COALESCE(
            NULLIF(u.fullname, ''),
            NULLIF(u.username, ''),
            'Unknown'
        ) AS collected_by,

        /* COLLECTOR ROLE */
        COALESCE(
            NULLIF(u.role, ''),
            'unknown'
        ) AS collector_role,

        /* COMMENTS */
        LEFT(
            COALESCE(NEW.comments, ''),
            255
        ) AS note,

        /* PAYMENT DATE */
        COALESCE(
            NEW.payment_date,
            NOW()
        ) AS created_at

    FROM customers c

    LEFT JOIN users u
        ON u.id = NEW.created_by

    LEFT JOIN sub_areas sa
        ON sa.id = c.sub_area_id
       AND sa.area_id = c.area_id

    LEFT JOIN areas a
        ON a.id = c.area_id

    WHERE c.id = NEW.customer_id

    LIMIT 1;

END */;;
DELIMITER ;
